contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(address newAlloSettings) public {
        require(newAlloSettings != address(0), "zero address is unusable as value");

        bool reverted;
        c.updateAlloSettings(newAlloSettings); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        assert(reverted || c.alloSettings() == newAlloSettings);
    }
}

